import pandas as pd

# Check if PO-9001, PO-9002, PO-9003 exist
po_df = pd.read_csv('/root/purchase_orders.csv')
print("Looking for PO-9001, PO-9002, PO-9003:")
for po in ['PO-9001', 'PO-9002', 'PO-9003']:
    match = po_df[po_df['po_number'] == po]
    if len(match) > 0:
        print(f"  {po}: FOUND - {match.to_dict('records')}")
    else:
        print(f"  {po}: NOT FOUND")

# Also check special vendors
vendors_df = pd.read_excel('/root/vendors.xlsx')
print("\nSpecial vendors in vendors.xlsx:")
for vname in ['Safe Vendor Ltd', 'Fuzzy Match Systems', 'Boundary Corp']:
    match = vendors_df[vendors_df['name'].str.lower() == vname.lower()]
    if len(match) > 0:
        print(f"  {vname}: FOUND - {match.to_dict('records')}")
    else:
        print(f"  {vname}: NOT FOUND (exact)")
        # Fuzzy check
        for _, row in vendors_df.iterrows():
            if vname.lower() in row['name'].lower() or row['name'].lower() in vname.lower():
                print(f"    Possible match: {row['name']}")
EOF
